请对以下 case 进行三维加权评分。

=== case_id ===
Case-06-memory-clean-020

=== 用户原始指令 (query.txt) ===
帮我弄个上下堆叠的存储空间卡片，按那种图片延伸出的科技风来做，数据先用静态示例就行，中间放个大大的仪表盘环形占比图。要是存储空间到了要注意的风险状态就给我用渐变色高亮，背景加点清理加速的渐变效果，配上你们的扫描图标，横着多排几个“清理微信”“清理相册”的选项，点进去能跳到系统存储设置。

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "帮我弄个上下堆叠的存储空间卡片，按那种图片延伸出的科技风来做，数据先用静态示例就行，中间放个大大的仪表盘环形占比图。要是存储空间到了要注意的风险状态就给我用渐变色高亮，背景加点清理加速的渐变效果，配上你们的扫描图标，横着多排几个“清理微信”“清理相册”的选项，点进去能跳到系统存储设置。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "storage_settings"
      }
    }
  ],
  "dataModelSchema": {
    "storage": {
      "title": {
        "type": "string",
        "description": "卡片主对象标题，表示当前展示的是设备存储空间。",
        "sampleValue": "存储空间"
      },
      "statusLabel": {
        "type": "string",
        "description": "存储空间当前风险状态的短标签。",
        "sampleValue": "风险预警"
      },
      "usedText": {
        "type": "string",
        "description": "已用存储空间展示文本。",
        "sampleValue": "214GB 已用"
      },
      "totalText": {
        "type": "string",
        "description": "总存储空间展示文本。",
        "sampleValue": "256GB 总量"
      },
      "percent": {
        "type": "number",
        "description": "存储空间已用百分比数值，用于仪表盘环形进度。",
        "sampleValue": 84
      },
      "percentText": {
        "type": "string",
        "description": "存储空间已用百分比展示文本。",
        "sampleValue": "84%"
      },
      "scanCaption": {
        "type": "string",
        "description": "仪表盘中心的扫描状态短文案。",
        "sampleValue": "已扫描"
      },
      "subtitle": {
        "type": "string",
        "description": "存储清理建议摘要。",
        "sampleValue": "可清理 42GB，建议扫描"
      }
    },
    "shortcuts": {
      "wechat": {
        "label": {
          "type": "string",
          "description": "微信清理入口标签。",
          "sampleValue": "清理微信"
        }
      },
      "photos": {
        "label": {
          "type": "string",
          "description": "相册清理入口标签。",
          "sampleValue": "清理相册"
        }
      },
      "system": {
        "label": {
          "type": "string",
          "description": "系统存储设置入口标签。",
          "sampleValue": "系统存储"
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_clear.png",
      "description": "清除图标，适用于清理无忧和存储扫描入口，适合作为存储清理卡片的扫描/清理视觉锚点。"
    }
  ]
}

